+      <D:prop>
+        <D:resourcetype>
+          <D:collection/>
+        </D:resourcetype>
+        <D:displayname>{displayname}</D:displayname>
+        <D:principal-URL>
+          <D:href>{}</D:href>
+        </D:principal-URL>
